using System;
using System.IO;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
[InitializeOnLoad] public static class StorybookCombatFloatAuthoring
{
 public const string Folder="Assets/DarkFairytale/UI/CombatFloat/",Out="output/combat-float/";
 static StorybookCombatFloatAuthoring(){EditorApplication.update+=()=>{if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(Out+"build.request"))return;File.Delete(Out+"build.request");try{Build();File.WriteAllText(Out+"build.txt","PASS");}catch(Exception e){File.WriteAllText(Out+"build.txt",e.ToString());}};}
 static Text Text(Transform parent,string name,int size,float y){var g=new GameObject(name,typeof(RectTransform),typeof(Text),typeof(Outline));g.transform.SetParent(parent,false);var r=(RectTransform)g.transform;r.anchorMin=r.anchorMax=r.pivot=new Vector2(.5f,.5f);r.sizeDelta=new Vector2(240,60);r.anchoredPosition=new Vector2(0,y);var t=g.GetComponent<Text>();t.font=AssetDatabase.LoadAssetAtPath<Font>("Assets/DarkFairytale/UI/CursedStorybook/Fonts/NotoSerifCJKsc-Black.otf");t.fontSize=size;t.alignment=TextAnchor.MiddleCenter;t.raycastTarget=false;t.resizeTextForBestFit=true;t.resizeTextMinSize=24;t.resizeTextMaxSize=size;t.text=name;var outline=g.GetComponent<Outline>();outline.effectColor=new Color(.065f,.035f,.025f,.95f);outline.effectDistance=new Vector2(2,-2);return t;}
 static GameObject Create(bool xp){string path=Folder+(xp?"StorybookDoubleExperience":"StorybookDamage")+".prefab";if(File.Exists(path))return AssetDatabase.LoadAssetAtPath<GameObject>(path);var root=new GameObject(xp?"StorybookDoubleExperience":"StorybookDamage",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(CanvasGroup),typeof(StorybookCombatFloat));try{var c=root.GetComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceOverlay;c.sortingOrder=85;var s=root.GetComponent<CanvasScaler>();s.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;s.referenceResolution=new Vector2(1080,1920);s.matchWidthOrHeight=0;var ui=root.GetComponent<StorybookCombatFloat>();ui.group=root.GetComponent<CanvasGroup>();ui.group.blocksRaycasts=ui.group.interactable=false;ui.experience=xp;ui.duration=xp?1.3f:.95f;var card=new GameObject("Float",typeof(RectTransform));card.transform.SetParent(root.transform,false);ui.card=(RectTransform)card.transform;ui.card.anchorMin=ui.card.anchorMax=Vector2.zero;ui.card.pivot=Vector2.one*.5f;ui.card.sizeDelta=new Vector2(240,108);ui.value=Text(card.transform,xp?"经验 ×2":"128",xp?34:52,-10);ui.caption=Text(card.transform,"暴击",26,32);ui.caption.gameObject.SetActive(false);ui.normalSize=xp?34:38;return PrefabUtility.SaveAsPrefabAsset(root,path);}finally{UnityEngine.Object.DestroyImmediate(root);}}
 [MenuItem("Tools/Dark Fairytale/UI/Create Combat Floats (Explicit)")]
 public static void Build(){Directory.CreateDirectory(Folder);var damage=Create(false);var xp=Create(true);EditorSceneManager.OpenScene("Assets/Scenes/MainScenes/Gameplay.unity");var am=UnityEngine.Object.FindFirstObjectByType<AssetManager>(FindObjectsInactive.Include);am.popUpText=damage;am.notifierText=xp;EditorUtility.SetDirty(am);EditorSceneManager.MarkSceneDirty(am.gameObject.scene);EditorSceneManager.SaveScene(am.gameObject.scene);AssetDatabase.SaveAssets();}
}
